// Generated by vibelang from src/features/sandbox/actions.ts; the migrate flow writes it again with each batch.
import { Effect, Option } from "effect";
import { PLACE } from "../chat/schema.js";
import { ChatStore } from "../chat/store.js";
// What a person's door does with a sandbox tool (docs/features/sandbox-tools.md#a-persons-door): `/run`, `/read`,
// `/write`, `/ls`, `/status` and `/diff` in the composer run the tool's flow, the one the agent calls, on the branch of
// the conversation this tab shows.
/**
 * `payload` with the conversation this tab shows now pinned in it (decision 0013 §1): switching branches before the
 * step runs, or a run resumed later, still calls the tool on that branch. A payload naming one keeps it.
 */
export const pinConversation = (payload) => Effect.gen(function* () {
    if (payload.conversationId !== undefined)
        return payload;
    const chat = yield* Effect.serviceOption(ChatStore);
    const place = Option.isSome(chat) ? Option.getOrUndefined(yield* chat.value.place.get(PLACE)) : undefined;
    const conversationId = place?.conversationId ?? undefined;
    return conversationId === undefined ? payload : { ...payload, conversationId };
});
